import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"湖仓与开放表格式","description":"","frontmatter":{"title":"湖仓与开放表格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lakehouse-table-format.md","filePath":"cs/lakehouse-table-format.md","lastUpdated":1789023840000}'),h={name:"cs/lakehouse-table-format.md"};function m(u,a,_,A,E,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="湖仓与开放表格式" tabindex="-1">湖仓与开放表格式 <a class="header-anchor" href="#湖仓与开放表格式" aria-label="Permalink to &quot;湖仓与开放表格式&quot;">​</a></h1><div class="epigraph"><p>对象存储上的 Parquet 不是表：没有事务、没有隔离、没有可靠的 schema 演进。表格式把数据湖补成可被引擎共享的关系。</p><footer>—— 据 Armbrust et al. 对 lakehouse；Delta Lake / Apache Iceberg / Apache Hudi 的公开设计</footer></div><p><a href="/cs/olap-cube">上一课</a>假定有一张可维护的事实表。缺口是文件堆：数仓一体机贵，HDFS 上的目录又没有 ACID。本课钉湖仓与开放表格式；MapReduce 下一课才讲批计算模型。不把对象存储当新的 B+ 树重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>湖：廉价存储 + schema-on-read，丢了主键、并发写、时间旅行。仓：强事务，锁进专有格式。表格式（Iceberg/Delta/Hudi）在对象存储上加：快照隔离、分区演进、列投影、可重放的提交日志。缺口是<strong>元数据如何成为真值</strong>，不是再夸一次列存。</p><p><span class="marginnote">多引擎（Spark、Trino、Flink）共用同一快照，才叫开放。只给一个引擎写的「湖」仍是专有仓。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一次提交：manifest / transaction log 指向不可变文件。写：copy-on-write 或 merge-on-read。compaction 把小文件合并。与立方：物化视图可以挂在表快照上。与流：changelog 表是后课 exactly-once 的落点。</p>',8)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%E6%96%87%E4%BB%B6%22%5D%20--%3E%20META%5B%22%E5%BF%AB%E7%85%A7%20%2F%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20META%20--%3E%20ENG%5B%22%E5%A4%9A%E5%BC%95%E6%93%8E%E5%8F%AA%E8%AF%BB%E5%90%8C%E4%B8%80%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不可变文件 + 原子换根指针 ≈ <a href="/cs/shadow-paging">影子分页</a> 在对象存储上的亲戚，也像 LSM 切根。隔离来自「读一个快照 ID」，不是行锁；跨表 2PC 通常没有或很弱，不要当 Spanner。小文件问题来自列出与打开成本，compaction 合并——表级 LSM。delete file / merge-on-read 让读时合并删除位，读放大上升。</p><p>并发写：条件 put 或锁服务提交元数据，冲突则 abort 重试。时间旅行等于选旧快照。schema 演进写进元数据，读侧按字段投影，与 <a href="/cs/schema-migration">模式迁移</a> 的文件版对齐。TDE 在对象存储侧，密钥合同单独写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较 Iceberg / Delta / Hudi 的每一条 SQL。下一课 MapReduce 是计算模型，不是表。不要把湖仓写成已经取代 OLTP：提交延迟与行锁粒度都不在同一档。流写入必须控制批次，否则小文件打爆元数据。</p><p>后课默认：分析表用开放格式快照；跨引擎共享的是文件集，不是缓冲池。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>表格式把对象存储补上快照与演进，才成为多引擎的表。</li><li>元数据日志是真值；数据文件只追加；compaction 管小文件。</li><li>MapReduce 下一课。</li><li>出处：Armbrust 等 lakehouse；Iceberg / Delta / Hudi 设计文档。</li></ul>',8))])}const B=l(h,[["render",m]]);export{T as __pageData,B as default};
